import numpy as np
def _gini(y):
    if len(y) == 0:
        return 0.0
    p = np.mean(y)
    return 1.0 - (p ** 2 + (1 - p) ** 2)
def best_split(X, y):
    X = np.asarray(X, float); y = np.asarray(y); N = len(y)
    best = float('inf')
    for f in range(X.shape[1]):
        for t in np.unique(X[:, f]):
            left = y[X[:, f] <= t]; right = y[X[:, f] > t]
            cost = len(left) / N * _gini(left) + len(right) / N * _gini(right)
            best = min(best, cost)
    return float(best)

import numpy as np
def gnb_predict(x_test, priors, means, variances):
    x = np.asarray(x_test, float)
    priors = np.asarray(priors, float); means = np.asarray(means, float); variances = np.asarray(variances, float)
    best_c, best = 0, -np.inf
    for c in range(len(priors)):
        ll = np.log(priors[c]) + np.sum(-0.5 * np.log(2 * np.pi * variances[c]) - (x - means[c]) ** 2 / (2 * variances[c]))
        if ll > best:
            best, best_c = ll, c
    return int(best_c)

