import numpy as np
def bert_mlm_loss(logits, targets, mask_indices):
    logits = np.asarray(logits, float); targets = np.asarray(targets); mask = np.asarray(mask_indices)
    idx = np.where(mask == 1)[0]
    if idx.size == 0:
        return 0.0
    z = logits[idx]; z = z - z.max(axis=1, keepdims=True)
    logp = z - np.log(np.exp(z).sum(axis=1, keepdims=True))
    return float(-logp[np.arange(idx.size), targets[idx]].mean())

