def scaled_dot_product_attention(Q, K, V, mask=None):
    Q = np.asarray(Q, float); K = np.asarray(K, float); V = np.asarray(V, float)
    d_k = Q.shape[-1]
    scores = Q @ K.T / np.sqrt(d_k)
    if mask is not None:
        scores = np.where(np.asarray(mask) == 0, -1e9, scores)
    return _softmax(scores) @ V

import numpy as np
def conv2d_forward(x, w, b, stride):
    x=np.asarray(x,float); w=np.asarray(w,float); b=np.asarray(b,float)
    F,C,KH,KW=w.shape; _,H,W=x.shape
    OH=(H-KH)//stride+1; OW=(W-KW)//stride+1
    out=np.empty((F,OH,OW),float)
    for f in range(F):
        for i in range(OH):
            for j in range(OW):
                out[f,i,j]=np.sum(x[:,i*stride:i*stride+KH,j*stride:j*stride+KW]*w[f])+b[f]
    return out

