    OH=(H-size)//stride+1; OW=(W-size)//stride+1
    out=np.empty((C,OH,OW),float)
    for c in range(C):
        for i in range(OH):
            for j in range(OW): out[c,i,j]=np.max(x[c,i*stride:i*stride+size,j*stride:j*stride+size])
    return out

