import numpy as np
def clip_contrastive_loss(img_embeds, txt_embeds, temperature):
    I=np.asarray(img_embeds,float); T=np.asarray(txt_embeds,float)
    I=I/np.maximum(np.linalg.norm(I,axis=-1,keepdims=True),1e-12)
    T=T/np.maximum(np.linalg.norm(T,axis=-1,keepdims=True),1e-12)
    S=I@T.T/float(temperature)
    def ce_rows(A):
        shifted=A-np.max(A,axis=1,keepdims=True)
        log_probs=shifted-np.log(np.sum(np.exp(shifted),axis=1,keepdims=True))
        return -np.mean(np.diag(log_probs))
    return 0.5*(ce_rows(S)+ce_rows(S.T))
